const WORD_RE = /\p{L}[\p{L}\p{M}'-]*/gu;
const SENTENCE_SPLIT_RE = /[.!?]+/u;

/**
 * Count words in text. Unicode letters and hyphenated/apostrophe forms count as one word.
 */
export function wordCount(text) {
	const matches = text.match(WORD_RE);
	return matches ? matches.length : 0;
}

/**
 * Count sentences delimited by `.`, `!`, or `?`.
 */
export function sentenceCount(text) {
	const trimmed = text.trim();
	if (!trimmed) {
		return 0;
	}

	return trimmed
		.split(SENTENCE_SPLIT_RE)
		.filter((segment) => segment.trim().length > 0).length;
}

/**
 * Lowercase character frequencies, excluding whitespace.
 */
export function charFrequency(text) {
	const freq = {};

	for (const ch of text) {
		if (/\s/u.test(ch)) {
			continue;
		}
		const key = ch.toLowerCase();
		freq[key] = (freq[key] ?? 0) + 1;
	}

	return freq;
}

/**
 * Estimated reading time in whole minutes at the given words-per-minute rate.
 */
export function readingTimeMinutes(text, wpm = 200) {
	if (wpm <= 0) {
		throw new RangeError("wpm must be greater than 0");
	}

	const words = wordCount(text);
	if (words === 0) {
		return 0;
	}

	return Math.ceil(words / wpm);
}

/**
 * Return the `n` most frequent words (case-insensitive), ties broken alphabetically.
 */
export function topWords(text, n = 10) {
	if (n < 0) {
		throw new RangeError("n must be 0 or greater");
	}

	const matches = text.match(WORD_RE) ?? [];
	const freq = new Map();

	for (const word of matches) {
		const key = word.toLowerCase();
		freq.set(key, (freq.get(key) ?? 0) + 1);
	}

	return [...freq.entries()]
		.sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
		.slice(0, n)
		.map(([word, count]) => ({ word, count }));
}

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, it } from "node:test";
import {
	charFrequency,
	readingTimeMinutes,
	sentenceCount,
	topWords,
	wordCount,
} from "./lib.mjs";

const __dirname = dirname(fileURLToPath(import.meta.url));

function readFixture(name) {
	return readFileSync(join(__dirname, "fixtures", name), "utf8");
}

describe("wordCount", () => {
	it("counts simple words", () => {
		assert.equal(wordCount("Hello world"), 2);
	});

	it("returns 0 for empty input", () => {
		assert.equal(wordCount(""), 0);
		assert.equal(wordCount("   "), 0);
	});

	it("returns 0 for punctuation-only text", () => {
		assert.equal(wordCount("... !!! ???"), 0);
	});

	it("counts unicode words", () => {
		assert.equal(wordCount("café résumé naïve"), 3);
		assert.equal(wordCount("日本語のテキスト"), 1);
	});

	it("counts hyphenated and apostrophe words", () => {
		assert.equal(wordCount("well-known don't"), 2);
	});
});

describe("sentenceCount", () => {
	it("counts sentences separated by terminators", () => {
		assert.equal(sentenceCount("One. Two! Three?"), 3);
	});

	it("returns 0 for empty input", () => {
		assert.equal(sentenceCount(""), 0);
		assert.equal(sentenceCount("   "), 0);
	});

	it("returns 0 for punctuation-only text", () => {
		assert.equal(sentenceCount("... !!!"), 0);
	});

	it("treats a single clause as one sentence", () => {
		assert.equal(sentenceCount("Just one sentence"), 1);
	});

	it("handles unicode text", () => {
		assert.equal(sentenceCount("Bonjour! Comment ça va?"), 2);
	});
});

describe("charFrequency", () => {
	it("counts non-whitespace characters case-insensitively", () => {
		assert.deepEqual(charFrequency("Aa b"), { a: 2, b: 1 });
	});

	it("returns an empty object for empty input", () => {
		assert.deepEqual(charFrequency(""), {});
		assert.deepEqual(charFrequency("   "), {});
	});

	it("ignores whitespace", () => {
		assert.deepEqual(charFrequency("a b\nc"), { a: 1, b: 1, c: 1 });
	});

	it("counts punctuation", () => {
		assert.deepEqual(charFrequency("!!!"), { "!": 3 });
	});

	it("handles unicode characters", () => {
		assert.deepEqual(charFrequency("é É"), { é: 2 });
	});
});

describe("readingTimeMinutes", () => {
	it("rounds up to whole minutes", () => {
		assert.equal(readingTimeMinutes("one two three four five"), 1);
	});

	it("returns 0 for empty text", () => {
		assert.equal(readingTimeMinutes(""), 0);
	});

	it("respects a custom wpm", () => {
		const text = Array.from({ length: 250 }, () => "word").join(" ");
		assert.equal(readingTimeMinutes(text, 100), 3);
	});

	it("rejects non-positive wpm", () => {
		assert.throws(() => readingTimeMinutes("hello", 0), RangeError);
	});
});

describe("topWords", () => {
	it("returns words sorted by frequency then alphabetically", () => {
		assert.deepEqual(topWords("beta alpha beta alpha gamma", 2), [
			{ word: "alpha", count: 2 },
			{ word: "beta", count: 2 },
		]);
	});

	it("returns an empty array for empty input", () => {
		assert.deepEqual(topWords(""), []);
	});

	it("returns an empty array for punctuation-only text", () => {
		assert.deepEqual(topWords("... !!!"), []);
	});

	it("is case-insensitive", () => {
		assert.deepEqual(topWords("Word word WORD", 1), [{ word: "word", count: 3 }]);
	});

	it("rejects negative n", () => {
		assert.throws(() => topWords("hello", -1), RangeError);
	});

	it("works with fixture content", () => {
		const sample = readFixture("sample.txt");
		const words = topWords(sample, 3);
		assert.equal(words.length, 3);
		assert.ok(words[0].count >= words[1].count);
	});
});

