#!/usr/bin/env node
import { readFileSync } from "node:fs";
import { createInterface } from "node:readline";
import {
	charFrequency,
	readingTimeMinutes,
	sentenceCount,
	topWords,
	wordCount,
} from "./lib.mjs";

function parseArgs(argv) {
	const options = { json: false, top: 10, file: null };

	for (let i = 0; i < argv.length; i += 1) {
		const arg = argv[i];
		if (arg === "--json") {
			options.json = true;
		} else if (arg === "--top") {
			const value = Number(argv[++i]);
			if (!Number.isInteger(value) || value < 0) {
				throw new Error("--top requires a non-negative integer");
			}
			options.top = value;
		} else if (arg === "--help" || arg === "-h") {
			options.help = true;
		} else if (arg.startsWith("-")) {
			throw new Error(`Unknown option: ${arg}`);
		} else if (options.file !== null) {
			throw new Error(`Unexpected extra argument: ${arg}`);
		} else {
			options.file = arg;
		}
	}

	return options;
}

function printHelp() {
	console.log(`Usage: node demo/textstat/cli.mjs [options] [file]

Read text from a file path or stdin and print statistics.

Options:
  --json       Print machine-readable JSON
  --top <n>    Number of top words to include (default: 10)
  -h, --help   Show this help message`);
}

async function readInput(file) {
	if (file) {
		return readFileSync(file, "utf8");
	}

	if (process.stdin.isTTY) {
		return "";
	}

	const chunks = [];
	for await (const chunk of process.stdin) {
		chunks.push(chunk);
	}

	return Buffer.concat(chunks).toString("utf8");
}

function summarize(text, topN) {
	return {
		words: wordCount(text),
		sentences: sentenceCount(text),
		characters: Object.values(charFrequency(text)).reduce(
			(sum, count) => sum + count,
			0,
		),
		readingTimeMinutes: readingTimeMinutes(text),
		topWords: topWords(text, topN),
	};
}

function printSummary(summary) {
	console.log(`Words: ${summary.words}`);
	console.log(`Sentences: ${summary.sentences}`);
	console.log(`Characters: ${summary.characters}`);
	console.log(`Reading time: ${summary.readingTimeMinutes} min`);
	console.log("Top words:");
	for (const { word, count } of summary.topWords) {
		console.log(`  ${word}: ${count}`);
	}
}

async function main(argv = process.argv.slice(2)) {
	try {
		const options = parseArgs(argv);
		if (options.help) {
			printHelp();
			return;
		}

		const text = await readInput(options.file);
		const summary = summarize(text, options.top);

		if (options.json) {
			console.log(JSON.stringify(summary, null, 2));
			return;
		}

		printSummary(summary);
	} catch (error) {
		console.error(error instanceof Error ? error.message : String(error));
		process.exitCode = 1;
	}
}

if (import.meta.url === new URL(process.argv[1], "file:").href) {
	main();
}

